// Validate the secret and normalise one line of inner voice into a TTS request.
//
// This endpoint says ONE thing that daemon/chat does not: it speaks text the
// caller already has. No model runs here. The dashboard has the aside on
// screen already -- it wants a voice for it, not a second opinion about it.
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body || {};
const expected = $env.DEX_SHARED_SECRET;
if (expected && headers['x-dex-secret'] !== expected) {
  throw new Error('Unauthorized: bad or missing x-dex-secret');
}

const raw = String(body.text || '').trim();
if (!raw) throw new Error('Missing text');

// The TTS server caps at 600 characters and returns a 422 past it. An aside
// is one or two sentences by construction, so hitting this means something
// upstream is wrong -- clip at a sentence end rather than mid-word, and say
// in the response that we did.
const MAX = 600;
let text = raw;
let truncated = false;
if (text.length > MAX) {
  const cut = text.slice(0, MAX);
  const lastStop = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  text = (lastStop > MAX * 0.5 ? cut.slice(0, lastStop + 1) : cut).trim();
  truncated = true;
}

// `index` is the blended voice -- nostalgia, logic, emotion -- and the INDEX
// is what this game calls its record of daemons (§4.2). Its own inner voice
// should sound like its own narrator. `dexter` is still reachable by asking.
const voice = String(body.voice || 'index');

// Slightly flatter than Dexter's default: this is a thought, not an
// announcement. The caller can override both.
const exaggeration = Number.isFinite(Number(body.exaggeration)) ? Number(body.exaggeration) : 0.35;
const cfg_weight = Number.isFinite(Number(body.cfg_weight)) ? Number(body.cfg_weight) : 0.5;
const rawAudio = body.raw === true;

return [{ json: { text, voice, exaggeration, cfg_weight, raw: rawAudio, truncated } }];

// mp3 -> base64, and say plainly when there is no audio.
//
// A silent play button that looks like it worked is worse than one that says
// the voice is down: the first sends you looking at your speakers.
const v = $('Validate + Normalise').first().json;
let audioBase64 = null;
let error = null;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (buf && buf.length) audioBase64 = buf.toString('base64');
} catch (e) {
  error = 'tts_unavailable';
}
if (!audioBase64 && !error) error = 'tts_empty';
return [{ json: {
  audioBase64,
  audioMime: audioBase64 ? 'audio/mpeg' : null,
  voice: v.voice,
  text: v.text,
  truncated: v.truncated || false,
  error,
} }];
